-- 074 DRY RUN - GENERATED by worker/migrations/drafts/tools/build-074.mjs from 074_plan_cutover.sql.
-- DO NOT EDIT BY HAND: edit the source and regenerate (tests/sql-074-drafts.test.js fails on any drift).
-- ONE DO block = ONE statement: its final error undoes everything inside it (lesson 056). ASCII only.
-- WHAT: 074's own DO block, statement for statement (guards, the bridge, the triggers, the freeze, 028 / 030, day L,
--   the backfill, the test rows, the proofs), then a read of the result, ENDING WITH A DELIBERATE ERROR: NOTHING kept.
-- WHEN: Thursday L-2 after 15:00 (the rehearsal P-8) and Friday L-1 after 15:00 (Runbook R-2), after 074a.
-- EXPECTED (the red ERROR is deliberate): a NOTICE "074 OK: ..." and then
--   ERROR: P0001: DRY RUN 074 finished - EVERYTHING UNDONE, nothing kept. The block ran to its end  ||  074 ran:
--   cutover <L>, bridges <n> on <m> VS, NL unlinked <m>, NL to re-record <k> [<ids>], tests cleaned 6/7/1/2, via_hub <n>, legs 0, triggers <B-54 + 6>
--   Write n / m / k / the ids into docs/sessions/. Anything else: do NOT run 074, copy the message to the coordinator.

DO $dry$
DECLARE
  res text;
BEGIN
  -- ===== 074_plan_cutover.sql, verbatim =====
DECLARE
  -- Q-1 (owner 28/10): day L = Saturday 31/10/2026, executed Friday 30/10 after 15:00. The ONE place the day is
  -- written; every reader takes it from plan_config (plan_cutover_day()). If the gate of Friday 15:00 moves L to 7/11,
  -- this line changes, with a new review.
  c_cutover_day CONSTANT date := DATE '2026-10-31';
  -- PART 7: the test rows of the old model, measured on production 28/10 (spec 2.2 step 1). Any other live row of
  -- these kinds = STOP: a real job was born in the old model since, and it is not ours to delete.
  c_tests_no CONSTANT bigint[] := '{5,6,7,8,13,14}';
  c_tests_nl CONSTANT bigint[] := '{93,96,97,98,99,102,103}';
  c_tests_cl CONSTANT bigint[] := '{5}';
  c_tests_gl CONSTANT bigint[] := '{52,53}';
  -- the live texts this block patches (028, 030, plan_vs_set_place) and the anchors of each patch
  a_028 CONSTANT text := E'  if d_cd <> 0 and new.veroia_switch then\n';
  b_028 CONSTANT text := E'  if d_cd <> 0 and new.veroia_switch and plan_cutover_day() is null then -- 074: from day L the old national loads follow nothing\n';
  a_030 CONSTANT text := E'  if target is null or not coalesce(new.veroia_switch, false) then return null; end if;\n';
  b_030 CONSTANT text := E'  if target is null or not coalesce(new.veroia_switch, false) or plan_cutover_day() is not null then return null; end if; -- 074: from day L the old national loads follow nothing\n';
  a_rp0 CONSTANT text := E'    -- the national end that moved: an import ENDS at the Greek stop, an export STARTS there\n';
  a_rp1 CONSTANT text := E'    -- the shipment''s own rules, now (071 plan_chk_bridge_stop does not fire on location_id)\n';
  b_rp CONSTANT text := E'    -- 074: the legs follow the new place through plan_h_vs_repoint, the ONE copy the F5 bridge calls too\n'
    || E'    select r.legs, r.stops into v_legs, v_stops\n'
    || E'      from plan_h_vs_repoint(v_sh, v_kind, v_old_loc, v_loc, w_repoint, p_actor, p_role) r;\n';
  rp_head CONSTANT text := E'\ndeclare\n'
    || E'  -- 074: the loop below is plan_vs_set_place''s own (072 B5, K-06), moved here byte for byte so the F5 bridge\n'
    || E'  -- re-points the legs with the SAME code when the international desk changes the place (principle 3)\n'
    || E'  v_sh bigint := p_sh; v_kind text := p_kind; v_old_loc bigint := p_old_loc; v_loc bigint := p_new_loc;\n'
    || E'  w_repoint text := p_reason; v_legs bigint[] := ''{}''; v_stops bigint[] := ''{}''; v_moved jsonb := ''{}''::jsonb;\n'
    || E'  v_old jsonb; v_new_stop bigint; v_new_leg bigint; rs rt_stops%rowtype; x record;\nbegin\n';
  rp_tail CONSTANT text := E'  legs := v_legs;\n  stops := v_stops;\nend\n';
  v_src text; v_new text; v_block text; v_p0 int; v_p1 int; v_g record; v_k int;
  v_trg0 int; v_trg1 int; v_today date; v_vs int := 0; v_sh int; v_nl int; v_nlveh text; v_via int;
  x record;
BEGIN
  PERFORM set_config('lock_timeout', '5s', true);
  v_today := (now() AT TIME ZONE 'Europe/Athens')::date;

  -- ===== PART 0: GUARDS (read only) =====
  IF (SELECT count(*) FROM monitoring.checks WHERE id IN ('B-78','B-79','B-80','B-81','B-82','B-83','B-84','B-85','B-86',
        'B-87','B-88','B-89','B-90','B-91','B-92','B-93','B-94')) <> 17 THEN
    RAISE EXCEPTION '074: 073b (B-78..B-94) must be applied first';
  END IF;
  IF to_regprocedure('public.plan_lookups(text)') IS NULL OR to_regclass('public.plan_config') IS NULL
     OR to_regprocedure('public.plan_cutover_day()') IS NULL OR to_regprocedure('public.plan_config_read()') IS NULL THEN
    RAISE EXCEPTION '074: 074a (plan_config, plan_cutover_day, plan_config_read, plan_lookups) must be applied first';
  END IF;
  IF (SELECT string_agg(column_name || ':' || data_type, ',' ORDER BY ordinal_position) FROM information_schema.columns
       WHERE table_schema = 'public' AND table_name = 'plan_config')
     IS DISTINCT FROM 'id:smallint,cutover_day:date,opened_at:timestamp with time zone,opened_by:text' THEN
    RAISE EXCEPTION '074: plan_config is not the table of plan Task B1 (id, cutover_day, opened_at, opened_by) - stop';
  END IF;
  IF EXISTS (SELECT 1 FROM public.plan_config) OR plan_cutover_day() IS NOT NULL THEN
    RAISE EXCEPTION '074: plan_config already holds day L - run 074_plan_cutover_verify.sql instead';
  END IF;
  IF to_regclass('public.plan_cutover_log') IS NOT NULL OR to_regprocedure('public.plan_bridge_sync(bigint,text)') IS NOT NULL THEN
    RAISE EXCEPTION '074: already applied (plan_cutover_log / plan_bridge_sync exist)';
  END IF;
  IF extract(isodow FROM c_cutover_day) <> 6 THEN
    RAISE EXCEPTION '074: day L % is not a Saturday', c_cutover_day USING ERRCODE = '23514', HINT = 'plan:bad_cutover_day';
  END IF;
  IF c_cutover_day <= v_today THEN
    RAISE EXCEPTION '074: day L % is not after today % (Athens)', c_cutover_day, v_today
      USING ERRCODE = '23514', HINT = 'plan:bad_cutover_day';
  END IF;
  -- the LIVE texts this block patches or relies on (md5 of prosrc, measured on production 28/10 by SELECT)
  FOR v_g IN SELECT * FROM (VALUES
      ('public.order_dates_follow()', '4b5d279f21f981a11d35a5deb655269a'),
      ('public.national_load_follow_order()', '66f079523fb3d7d91dd196b0df272e9a'),
      ('public.plan_vs_set_place(jsonb,text,text)', '8a7280968075a8a56c9a42edd4b47e24'),
      ('public.plan_h_rt_cancel_if_empty(bigint,text,text,text)', '2f3cdfe09caa8c548e5a30e0f06c84fa'),
      ('public.plan_h_rt_consequences(bigint)', 'cddea3a5fb20a563283a16db3b50f133'),
      ('public.plan_h_drop_consequences(bigint[],bigint,bigint[])', 'e370e52c9dd96d7e4e152b3ce348736e'),
      ('public.plan_h_stops_sweep(bigint[],text,text,text)', 'e95fbdd0ad5f082f8895165c726b67ef'),
      ('public.plan_h_seg_cut(jsonb,text,text,text)', 'f34d11e573939aaed637081120d7a9d6'),
      ('public.plan_h_vs_day(bigint,date,text,text)', 'f9620e4c49fd4e96ab1513e91a529ae7'),
      ('public.plan_chk()', '8f2fa7e5541aded2dffc853a57c54c22')
    ) g(sig, m) LOOP
    IF to_regprocedure(v_g.sig) IS NULL
       OR (SELECT md5(prosrc) FROM pg_proc WHERE oid = to_regprocedure(v_g.sig)) IS DISTINCT FROM v_g.m THEN
      RAISE EXCEPTION '074: % is not the live text measured 28/10 (expected md5 %) - stop, re-measure', v_g.sig, v_g.m;
    END IF;
  END LOOP;
  IF (SELECT count(*) FROM public.locations WHERE is_hub) <> 1 THEN RAISE EXCEPTION '074: not exactly one hub'; END IF;
  SELECT count(*) INTO v_trg0 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid
    JOIN pg_namespace ns ON ns.oid = c.relnamespace WHERE NOT t.tgisinternal AND t.tgenabled <> 'D' AND ns.nspname = 'public';
  IF NOT EXISTS (SELECT 1 FROM monitoring.checks WHERE id = 'B-54' AND red_value = v_trg0 AND baseline IS NULL) THEN
    RAISE EXCEPTION '074: B-54 red_value is not the live trigger count % - re-measure', v_trg0;
  END IF;
  -- no v5 row before day L; the only ones allowed are what an earlier 074 left after its own rollback (its bridges
  -- soft-deleted '074 rollback', its notices) - the rollback's R3 case: apply again, same result
  IF (SELECT count(*) FROM public.shipments WHERE deleted_reason IS DISTINCT FROM '074 rollback')
     + (SELECT count(*) FROM public.shipment_pieces WHERE deleted_reason IS DISTINCT FROM '074 rollback')
     + (SELECT count(*) FROM public.rt_stops) + (SELECT count(*) FROM public.piece_legs)
     + (SELECT count(*) FROM public.plan_notices WHERE created_by NOT IN ('074 backfill', 'trigger:plan_bridge_sync'))
     + (SELECT count(*) FROM public.ct_round_trips WHERE model = 2) <> 0 THEN
    RAISE EXCEPTION '074: v5 rows exist before day L - stop, ask';
  END IF;
  IF EXISTS (SELECT 1 FROM public.national_loads nl JOIN public.orders o ON o.id = nl.source_order_id
              WHERE o.veroia_switch AND o.deleted_at IS NULL AND nl.source_type = 'Direct' AND nl.deleted_at IS NULL
              GROUP BY o.id HAVING count(*) > 1) THEN
    RAISE EXCEPTION '074: a live VS has more than one live Direct national load - stop, re-measure';
  END IF;
  IF EXISTS (SELECT 1 FROM public.order_stops WHERE via_hub) THEN
    RAISE EXCEPTION '074: order_stops.via_hub is true somewhere before day L (only 074 writes it, Q-6) - stop';
  END IF;

  -- ===== PART 1: THE TRACE FOR THE ROLLBACK =====
  CREATE TABLE public.plan_cutover_log (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    kind text NOT NULL CHECK (kind IN ('nl_unlinked', 'test_cleanup', 'gl_unassigned')),
    table_name text NOT NULL,
    row_id bigint NOT NULL,
    at timestamptz NOT NULL DEFAULT now(),
    reason text NOT NULL,
    before_data jsonb
  );
  ALTER TABLE public.plan_cutover_log ENABLE ROW LEVEL SECURITY;
  REVOKE ALL ON public.plan_cutover_log FROM PUBLIC, anon, authenticated, service_role;

  -- ===== PART 2: THE BRIDGE =====
  -- The national side of a VS stop: import -> its Greek deliveries (Unloading), export -> its Greek loadings
  -- (Loading). Never the Cross-dock stop (that is the hub itself), never the country: production writes it as
  -- 'Greece', 'GR' or not at all (measured 28/10).
  CREATE FUNCTION public.plan_h_vs_nat_side(p_direction text, p_stop_type text) RETURNS boolean
    LANGUAGE sql IMMUTABLE SET search_path = public AS $f$
  select coalesce((p_direction = 'Import' and p_stop_type = 'Unloading') or (p_direction = 'Export' and p_stop_type = 'Loading'), false)
$f$;

  -- The cut (plan section 1, owner 28/10: Q-2 the HUB day for imports and exports alike, Q-5 Cancelled = VS off):
  -- a live VS, not Cancelled, with its hub day on or after day L - or one that was ever bridged ("once v5, always
  -- v5": its national load is gone, so a move back before L can never return it to the old model).
  CREATE FUNCTION public.plan_h_vs_in_v5(p_order bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$
  select coalesce((
    select o.deleted_at is null and o.veroia_switch is true and o.status is distinct from 'Cancelled'
       and plan_cutover_day() is not null
       and ((o.cross_dock_date is not null and o.cross_dock_date >= plan_cutover_day())
            or exists (select 1 from shipments s where s.order_id = o.id and s.order_stop_id is not null
                          and s.deleted_reason is distinct from '074 rollback'))
      from orders o where o.id = p_order), false)
$f$;

  -- A stop that must carry a live bridge: live, with pallets (a piece is > 0, 071), on the national side of a VS
  -- that is in v5. ONE definition: plan_bridge_sync writes by it, B-95 / B-99 (074b) read by it.
  CREATE FUNCTION public.plan_h_bridge_wanted(p_stop bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$
  select coalesce((
    select s.deleted_at is null and coalesce(s.pallets, 0) > 0 and plan_h_vs_nat_side(o.direction, s.stop_type)
       and plan_h_vs_in_v5(o.id)
      from order_stops s join orders o on o.id = s.order_id where s.id = p_stop), false)
$f$;

  -- A shipment whose national leg already happened (spec 2.3: the Athens day of a drop stop has passed on a cycle
  -- that is not cancelled). History is never deleted by a change of the international.
  CREATE FUNCTION public.plan_h_bridge_executed(p_sh bigint) RETURNS boolean
    LANGUAGE sql STABLE SET search_path = public AS $f$
  select exists (select 1 from piece_legs l join shipment_pieces sp on sp.id = l.piece_id
                   join v_rt_stop_state ss on ss.stop_id = l.drop_stop_id
                  where sp.shipment_id = p_sh and l.deleted_at is null and ss.executed)
$f$;

  -- plan_h_vs_repoint: plan_vs_set_place's loop, taken out of the LIVE text (never retyped, plan B2) and called from
  -- there and from the bridge. Generated below, with md5 proofs of both texts.
  SELECT prosrc INTO v_src FROM pg_proc WHERE oid = 'public.plan_vs_set_place(jsonb,text,text)'::regprocedure;
  v_p0 := strpos(v_src, a_rp0);
  v_p1 := strpos(v_src, a_rp1);
  IF v_p0 = 0 OR v_p1 = 0 OR v_p1 < v_p0
     OR (length(v_src) - length(replace(v_src, a_rp0, ''))) <> length(a_rp0)
     OR (length(v_src) - length(replace(v_src, a_rp1, ''))) <> length(a_rp1) THEN
    RAISE EXCEPTION '074: the re-point loop of plan_vs_set_place is not found exactly once - stop';
  END IF;
  v_block := substr(v_src, v_p0, v_p1 - v_p0);
  v_new := rp_head || v_block || rp_tail;
  IF md5(v_new) <> 'e2ea8e50e4dda906fc97932cd5bfdd74' THEN
    RAISE EXCEPTION '074: the generated plan_h_vs_repoint is not the one measured (md5 %) - stop', md5(v_new);
  END IF;
  EXECUTE format('CREATE FUNCTION public.plan_h_vs_repoint(p_sh bigint, p_kind text, p_old_loc bigint, p_new_loc bigint, '
    || 'p_reason text, p_actor text, p_role text, OUT legs bigint[], OUT stops bigint[]) '
    || 'LANGUAGE plpgsql SET search_path = public AS %L', v_new);
  v_new := substr(v_src, 1, v_p0 - 1) || b_rp || substr(v_src, v_p1);
  IF md5(v_new) <> 'c8814ab08d0a86cfb77b79a89b9ba8a8' THEN
    RAISE EXCEPTION '074: the generated plan_vs_set_place is not the one measured (md5 %) - stop', md5(v_new);
  END IF;
  EXECUTE format('CREATE OR REPLACE FUNCTION public.plan_vs_set_place(p jsonb, p_actor text, p_role text) RETURNS jsonb '
    || 'LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS %L', v_new);

  -- Legs that go because the international changed (day, pallets, stop, VS off): the steps of plan_delete (072 B4,
  -- with 072b's handover cut), in its lock order - the cycles by id first. Q-4 (owner 28/10, (a)): a cycle left
  -- empty is cancelled ONLY without money (payroll with amounts, cost lines, a local loading); with money it stays empty, the
  -- national desk is told, B-82 shows it, and the desk decides with the Cleanup list. Money never goes silently.
  CREATE FUNCTION public.plan_h_bridge_drop(p_legs bigint[], p_reason text, p_actor text, p_role text) RETURNS void
    LANGUAGE plpgsql SET search_path = public AS $f$
declare v_rts bigint[]; v_full jsonb; v_stops bigint[]; v_leg bigint; v_rt bigint; v_docs bigint[];
begin
  if coalesce(cardinality(p_legs), 0) = 0 then return; end if;
  -- plan B2: the international's transaction already holds its orders / order_stops row and comes here for the
  -- cycles, the reverse of every plan_* (cycles first). A bounded wait: 55P03 (or the deadlock detector's 40P01)
  -- reaches the Worker as busy_retry, never an endless save. Set only when the caller set none.
  if current_setting('lock_timeout') in ('0', '') then perform set_config('lock_timeout', '5s', true); end if;
  select coalesce(array_agg(distinct rt_id), '{}') into v_rts from piece_legs where id = any (p_legs);
  perform 1 from ct_round_trips c where c.id = any (v_rts) order by c.id for no key update;
  v_full := plan_h_drop_consequences(p_legs, null);
  -- Q-4: a local loading is a document too (its TOPIKO line); read it before the sweep takes it with its stop
  select coalesce(array_agg(distinct s.rt_id), '{}') into v_docs from local_moves lm join rt_stops s on s.id = lm.rt_stop_id
   where s.rt_id = any (v_rts) and lm.move_kind = 'nat_loading' and lm.deleted_at is null and lm.status <> 'Cancelled';
  select coalesce(array_agg(distinct q), '{}') into v_stops
    from piece_legs l, unnest(array[l.pickup_stop_id, l.drop_stop_id]) q where l.id = any (p_legs);
  foreach v_leg in array p_legs loop
    perform plan_h_leg_drop(v_leg, p_reason, p_actor, p_role);
  end loop;
  perform plan_h_stops_sweep(v_stops, p_reason, p_actor, p_role);
  perform plan_h_seg_cut(v_full, '074 bridge', p_actor, p_role);
  foreach v_rt in array v_rts loop
    if exists (select 1 from piece_legs where rt_id = v_rt and deleted_at is null) then
      perform plan_h_reseq(v_rt, p_actor, p_role);
    elsif not (v_rt = any (v_docs)) and plan_h_rt_consequences(v_rt) = '[]'::jsonb then
      perform plan_h_rt_cancel_if_empty(v_rt, p_reason, p_actor, p_role);
    else
      -- "O kyklos %s adeiase alla echei misthodosia i exoda: den akyrothike, apofasi ston Katharismo"
      perform plan_h_notice('natl', 'rt_empty_kept',
        'zp8gzrrPjc66zrvOv8+CICVzIM6szrTOtc65zrHPg861IM6xzrvOu86sIM6tz4fOtc65IM68zrnPg864zr/OtM6/z4POr86xIM6uIM6tzr7Ov860zrE6IM60zrXOvSDOsc66z4XPgc+OzrjOt866zrUsIM6xz4DPjM+GzrHPg863IM+Dz4TOv869IM6azrHOuM6xz4HOuc+DzrzPjA==',
        array[(select code from ct_round_trips where id = v_rt)], null, null, v_rt, p_actor, p_role);
    end if;
  end loop;
end
$f$;

  -- A bridge that must go (its stop is no longer wanted: VS off, Cancelled, deleted, the stop deleted or moved to
  -- the other side). With an executed leg on a stop / order that still lives the bridge stays and the desk is told
  -- (B-95 then shows it red until a person decides). A DELETE is never refused (owner 28/10: the international or its
  -- national stop may be deleted after the national leg ran): everything goes soft, with its audit rows, after the
  -- E19 preview has listed the executed leg; a cycle with money stays (Q-4) - 071's pieces_sum needs it gone anyway.
  CREATE FUNCTION public.plan_h_bridge_retire(p_sh bigint, p_reason text, p_actor text, p_role text) RETURNS void
    LANGUAGE plpgsql SET search_path = public AS $f$
declare s shipments%rowtype; v_live boolean; v_ref text; v_legs bigint[]; x record;
begin
  select * into s from shipments where id = p_sh and deleted_at is null for no key update;
  if s.id is null then return; end if;
  select vs.live, coalesce(vs.reference, s.order_id::text) into v_live, v_ref from v_shipments vs where vs.shipment_id = p_sh;
  if v_live and plan_h_bridge_executed(p_sh) then
    -- "I VS %s allaxe meta tin ektelesi tou ethnikou skelous (%s): elegxe to fortigo"
    perform plan_h_notice('natl', 'vs_changed_after_execution',
      'zpcgVlMgJXMgzqzOu867zrHOvs61IM68zrXPhM6sIM+EzrfOvSDOtc66z4TOrc67zrXPg863IM+Ezr/PhSDOtc64zr3Ouc66zr/PjSDPg866zq3Ou86/z4XPgiAoJXMpOiDOrc67zrXOs86+zrUgz4TOvyDPhs6/z4HPhM63zrPPjA==',
      array[v_ref, p_reason], s.order_id, null, null, p_actor, p_role);
    return;
  end if;
  select coalesce(array_agg(l.id order by l.id), '{}') into v_legs
    from piece_legs l join shipment_pieces sp on sp.id = l.piece_id where sp.shipment_id = p_sh and l.deleted_at is null;
  perform plan_h_bridge_drop(v_legs, p_reason, p_actor, p_role);
  for x in select sp.id, to_jsonb(sp) as old from shipment_pieces sp
            where sp.shipment_id = p_sh and sp.deleted_at is null order by sp.id for no key update loop
    update shipment_pieces set deleted_at = now(), deleted_reason = p_reason, deleted_by = p_actor where id = x.id;
    perform plan_h_audit(p_actor, p_role, 'delete', 'shipment_pieces', x.id::text, x.old,
                         (select to_jsonb(q) from shipment_pieces q where q.id = x.id));
  end loop;
  update shipments set deleted_at = now(), deleted_reason = p_reason, deleted_by = p_actor where id = p_sh;
  perform plan_h_audit(p_actor, p_role, 'delete', 'shipments', p_sh::text, to_jsonb(s),
                       (select to_jsonb(q) from shipments q where q.id = p_sh));
  -- "I VS %s vgike apo ta ethnika (%s): ta kommatia tis aposyrthikan"
  perform plan_h_notice('natl', 'vs_withdrawn',
    'zpcgVlMgJXMgzrLOs86uzrrOtSDOsc+Az4wgz4TOsSDOtc64zr3Ouc66zqwgKCVzKTogz4TOsSDOus6/zrzOvM6sz4TOuc6xIM+EzrfPgiDOsc+Azr/Pg8+Nz4HOuM63zrrOsc69',
    array[v_ref, p_reason], s.order_id, null, null, p_actor, p_role);
end
$f$;

  -- The international desk moved the day (its hub day, or the day of a national-side stop): what was planned no
  -- longer holds. Not when the national desk wrote it (plan.writer = 'natl', 072 decision 17: the VS stays on its
  -- truck, C11). The legs that did not happen go, a split is undone (the root is one leaf again with the stop's
  -- pallets) and the pieces wait "TO ASSIGN". With an executed leg nothing moves: the desk is told (C20).
  CREATE FUNCTION public.plan_h_bridge_unplan(p_order bigint, p_stop bigint, p_reason text, p_actor text, p_role text)
    RETURNS void LANGUAGE plpgsql SET search_path = public AS $f$
declare v_sh bigint[]; v_legs bigint[]; v_ref text; v_done boolean := false; x record;
begin
  select coalesce(array_agg(s.id order by s.id), '{}') into v_sh from shipments s
   where s.order_id = p_order and s.order_stop_id is not null and s.deleted_at is null
     and (p_stop is null or s.order_stop_id = p_stop);
  if cardinality(v_sh) = 0 then return; end if;
  select coalesce(reference, id::text) into v_ref from orders where id = p_order;
  if exists (select 1 from unnest(v_sh) q where plan_h_bridge_executed(q)) then
    perform plan_h_notice('natl', 'vs_changed_after_execution',
      'zpcgVlMgJXMgzqzOu867zrHOvs61IM68zrXPhM6sIM+EzrfOvSDOtc66z4TOrc67zrXPg863IM+Ezr/PhSDOtc64zr3Ouc66zr/PjSDPg866zq3Ou86/z4XPgiAoJXMpOiDOrc67zrXOs86+zrUgz4TOvyDPhs6/z4HPhM63zrPPjA==',
      array[v_ref, p_reason], p_order, null, null, p_actor, p_role);
    return;
  end if;
  select coalesce(array_agg(l.id order by l.id), '{}') into v_legs
    from piece_legs l join shipment_pieces sp on sp.id = l.piece_id
   where sp.shipment_id = any (v_sh) and l.deleted_at is null;
  if cardinality(v_legs) > 0 then
    perform plan_h_bridge_drop(v_legs, p_reason, p_actor, p_role);
    v_done := true;
  end if;
  -- the split is undone: children off, the root takes the stop's pallets again (071 pieces_sum at COMMIT)
  for x in select sp.id, to_jsonb(sp) as old from shipment_pieces sp
            where sp.shipment_id = any (v_sh) and sp.parent_piece_id is not null and sp.deleted_at is null
            order by sp.id for no key update loop
    update shipment_pieces set deleted_at = now(), deleted_reason = p_reason, deleted_by = p_actor where id = x.id;
    perform plan_h_audit(p_actor, p_role, 'delete', 'shipment_pieces', x.id::text, x.old,
                         (select to_jsonb(q) from shipment_pieces q where q.id = x.id));
    v_done := true;
  end loop;
  for x in select sp.id, sp.pallets, st.pallets as want from shipment_pieces sp join shipments s on s.id = sp.shipment_id
             join order_stops st on st.id = s.order_stop_id
            where sp.shipment_id = any (v_sh) and sp.parent_piece_id is null and sp.deleted_at is null
              and coalesce(st.pallets, 0) > 0 and sp.pallets <> st.pallets order by sp.id loop
    update shipment_pieces set pallets = x.want where id = x.id;
    perform plan_h_audit(p_actor, p_role, 'update', 'shipment_pieces', x.id::text,
                         jsonb_build_object('pallets', x.pallets), jsonb_build_object('pallets', x.want));
  end loop;
  if v_done then
    -- "O diethnon allaxe tin imera Veroias tis VS %s: ta kommatia xanavgikan PROS ANATHESI"
    perform plan_h_notice('natl', 'vs_day_moved',
      'zp8gzrTOuc61zrjOvc+Ozr0gzqzOu867zrHOvs61IM+EzrfOvSDOt868zq3Pgc6xIM6Szq3Pgc6/zrnOsc+CIM+EzrfPgiBWUyAlczogz4TOsSDOus6/zrzOvM6sz4TOuc6xIM6+zrHOvc6xzrLOs86uzrrOsc69IM6gzqHOn86jIM6Rzp3Okc6YzpXOo86X',
      array[v_ref], p_order, null, null, p_actor, p_role);
  end if;
end
$f$;

  -- The international changed the pallets of a bridged stop (spec 3 VS): the leaves follow before COMMIT, where
  -- 071's pieces_sum is the net. One leaf: it takes the new number. Split: a reduction comes off the stock of the
  -- same shipment first (a child without a leg of its own, at the hub), then off the piece of the first day; an
  -- increase goes to the piece of the first day. A leaf left with 0 goes (its legs first). Told before execution
  -- only: after it the change is a correction.
  CREATE FUNCTION public.plan_h_bridge_recut(p_sh bigint, p_reason text, p_actor text, p_role text) RETURNS void
    LANGUAGE plpgsql SET search_path = public AS $f$
declare
  v_target numeric; v_sum numeric; v_left numeric; v_take numeric; v_order bigint; v_ref text; v_legs bigint[];
  lf record;
begin
  select st.pallets, s.order_id into v_target, v_order
    from shipments s join order_stops st on st.id = s.order_stop_id where s.id = p_sh and s.deleted_at is null;
  if coalesce(v_target, 0) <= 0 then return; end if;   -- not wanted any more: plan_bridge_sync retires it
  perform 1 from shipment_pieces where shipment_id = p_sh and deleted_at is null order by id for no key update;
  select coalesce(sum(pallets), 0) into v_sum from v_piece_state where shipment_id = p_sh;
  if v_sum = v_target then return; end if;
  if (select count(*) from v_piece_state where shipment_id = p_sh) = 1 then
    select piece_id, pallets into lf from v_piece_state where shipment_id = p_sh;
    update shipment_pieces set pallets = v_target where id = lf.piece_id;
    perform plan_h_audit(p_actor, p_role, 'update', 'shipment_pieces', lf.piece_id::text,
                         jsonb_build_object('pallets', lf.pallets), jsonb_build_object('pallets', v_target));
  elsif v_target > v_sum then
    select ps.piece_id, ps.pallets into lf from v_piece_state ps where ps.shipment_id = p_sh
     order by (select min(s.planned_from) from piece_legs l join rt_stops s on s.id = l.pickup_stop_id
                where l.piece_id = ps.piece_id and l.deleted_at is null) nulls last, ps.piece_id limit 1;
    update shipment_pieces set pallets = pallets + (v_target - v_sum) where id = lf.piece_id;
    perform plan_h_audit(p_actor, p_role, 'update', 'shipment_pieces', lf.piece_id::text,
                         jsonb_build_object('pallets', lf.pallets), jsonb_build_object('pallets', lf.pallets + v_target - v_sum));
  else
    v_left := v_sum - v_target;
    for lf in select ps.piece_id, ps.pallets from v_piece_state ps where ps.shipment_id = p_sh
               order by ps.is_stock desc,
                        (select min(s.planned_from) from piece_legs l join rt_stops s on s.id = l.pickup_stop_id
                          where l.piece_id = ps.piece_id and l.deleted_at is null) nulls last, ps.piece_id loop
      exit when v_left <= 0;
      v_take := least(v_left, lf.pallets);
      if v_take = lf.pallets then
        select coalesce(array_agg(id order by id), '{}') into v_legs from piece_legs where piece_id = lf.piece_id and deleted_at is null;
        perform plan_h_bridge_drop(v_legs, p_reason, p_actor, p_role);
        update shipment_pieces set deleted_at = now(), deleted_reason = p_reason, deleted_by = p_actor where id = lf.piece_id;
        perform plan_h_audit(p_actor, p_role, 'delete', 'shipment_pieces', lf.piece_id::text,
                             jsonb_build_object('pallets', lf.pallets, 'deleted_at', null),
                             jsonb_build_object('deleted_at', now(), 'reason', p_reason));
      else
        update shipment_pieces set pallets = pallets - v_take where id = lf.piece_id;
        perform plan_h_audit(p_actor, p_role, 'update', 'shipment_pieces', lf.piece_id::text,
                             jsonb_build_object('pallets', lf.pallets), jsonb_build_object('pallets', lf.pallets - v_take));
      end if;
      v_left := v_left - v_take;
    end loop;
    if v_left > 0 then perform plan_h_raise('bridge_recut', format('%s:%s', p_sh, v_left)); end if;
  end if;
  if not plan_h_bridge_executed(p_sh) then
    select coalesce(reference, id::text) into v_ref from orders where id = v_order;
    -- "O diethnon allaxe tis paletes tis VS %s: %s -> %s"
    perform plan_h_notice('natl', 'vs_pallets_changed',
      'zp8gzrTOuc61zrjOvc+Ozr0gzqzOu867zrHOvs61IM+EzrnPgiDPgM6xzrvOrc+EzrXPgiDPhM63z4IgVlMgJXM6ICVzIOKGkiAlcw==',
      array[v_ref, v_sum::text, v_target::text], v_order, null, null, p_actor, p_role);
  end if;
end
$f$;

  -- The international changed the place of a bridged stop: the legs follow with the SAME helper plan_vs_set_place
  -- uses (plan_h_vs_repoint, principle 3), the cycles locked first by id (072's lock order).
  CREATE FUNCTION public.plan_h_bridge_place(p_stop bigint, p_old bigint, p_new bigint, p_actor text, p_role text)
    RETURNS void LANGUAGE plpgsql SET search_path = public AS $f$
declare v_sh bigint; v_kind text; v_ref text; v_order bigint; v_rp record;
begin
  select s.id, vs.kind, coalesce(vs.reference, s.order_id::text), s.order_id into v_sh, v_kind, v_ref, v_order
    from shipments s join v_shipments vs on vs.shipment_id = s.id
   where s.order_stop_id = p_stop and s.deleted_at is null;
  if v_sh is null or p_old is not distinct from p_new then return; end if;
  perform 1 from ct_round_trips c
   where c.id in (select l.rt_id from piece_legs l join shipment_pieces sp on sp.id = l.piece_id
                   where sp.shipment_id = v_sh and l.deleted_at is null)
   order by c.id for no key update;
  select * into v_rp from plan_h_vs_repoint(v_sh, v_kind, p_old, p_new,
    -- "Allagi topou VS apo ton diethnon" (the reason on a re-pointed leg)
    convert_from(decode('zpHOu867zrHOs86uIM+Ez4zPgM6/z4UgVlMgzrHPgM+MIM+Ezr/OvSDOtM65zrXOuM69z47OvQ==', 'base64'), 'UTF8'),
    p_actor, p_role);
  -- "O diethnon allaxe ton proorismo tis VS %s: %s -> %s"
  perform plan_h_notice('natl', 'vs_place_changed',
    'zp8gzrTOuc61zrjOvc+Ozr0gzqzOu867zrHOvs61IM+Ezr/OvSDPgM+Bzr/Ov8+BzrnPg868z4wgz4TOt8+CIFZTICVzOiAlcyDihpIgJXM=',
    array[v_ref, coalesce((select name from locations where id = p_old), '-'), coalesce((select name from locations where id = p_new), '-')],
    v_order, null, null, p_actor, p_role);
end
$f$;

  -- THE SYNC (idempotent): the live bridges of an order = its wanted stops. A wanted stop without a bridge gets one
  -- (a shipment that copies nothing, 071, and one piece with the stop's pallets); a bridge on a stop that is not
  -- wanted goes (plan_h_bridge_retire); via_hub = wanted, written only here (Q-6). When a bridge is born, the
  -- order's live Direct national load is unlinked (soft delete) IN THE SAME TRANSACTION (spec 2.2 step 2), its id in
  -- plan_cutover_log for the rollback; with a vehicle on it the national desk is told (Q-3).
  CREATE FUNCTION public.plan_bridge_sync(p_order bigint, p_why text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$
declare
  v_actor text := coalesce(nullif(btrim(p_why), ''), 'trigger:plan_bridge_sync');
  v_role constant text := 'system';
  st record; v_w boolean; v_sh bigint; v_new int := 0; v_p shipment_pieces%rowtype; v_s shipments%rowtype;
  v_ref text; nl record;
begin
  if plan_cutover_day() is null then return; end if;
  -- a bridge whose stop moved to another order (or lost it) is not this order's any more
  for v_sh in select s.id from shipments s join order_stops os on os.id = s.order_stop_id
               where s.order_id = p_order and s.deleted_at is null and os.order_id is distinct from p_order order by s.id loop
    perform plan_h_bridge_retire(v_sh, v_actor, v_actor, v_role);
  end loop;
  for st in select s.id, s.via_hub, s.pallets from order_stops s where s.order_id = p_order order by s.id loop
    v_w := plan_h_bridge_wanted(st.id);
    select id into v_sh from shipments where order_stop_id = st.id and deleted_at is null;
    if v_w and v_sh is null then
      insert into shipments (order_id, order_stop_id, created_by) values (p_order, st.id, v_actor) returning * into v_s;
      perform plan_h_audit(v_actor, v_role, 'create', 'shipments', v_s.id::text, null, to_jsonb(v_s));
      insert into shipment_pieces (shipment_id, pallets, created_by) values (v_s.id, st.pallets, v_actor) returning * into v_p;
      perform plan_h_audit(v_actor, v_role, 'create', 'shipment_pieces', v_p.id::text, null, to_jsonb(v_p));
      v_new := v_new + 1;
    elsif not v_w and v_sh is not null then
      perform plan_h_bridge_retire(v_sh, v_actor, v_actor, v_role);
    end if;
    if st.via_hub is distinct from v_w then
      update order_stops set via_hub = v_w where id = st.id;
    end if;
  end loop;
  if v_new > 0 then
    -- every old Direct NL is unlinked, Delivered ones too (owner 28/10: the old national data has no business value
    -- and never blocks v5 - an old VS moved onto day L or later takes the normal bridge path); its id stays in
    -- plan_cutover_log and the soft delete is audited
    select coalesce(reference, id::text) into v_ref from orders where id = p_order;
    for nl in update national_loads set deleted_at = now()
               where source_order_id = p_order and source_type = 'Direct' and deleted_at is null
               returning id, legacy_id, truck_id, partner_id, status loop
      insert into plan_cutover_log (kind, table_name, row_id, reason, before_data)
      values ('nl_unlinked', 'national_loads', nl.id, v_actor,
              jsonb_build_object('order_id', p_order, 'truck_id', nl.truck_id, 'partner_id', nl.partner_id, 'status', nl.status));
      perform plan_h_audit(v_actor, v_role, 'delete', 'national_loads', coalesce(nl.legacy_id, nl.id::text),
                           jsonb_build_object('deleted_at', null), jsonb_build_object('deleted_at', now(), 'reason', 'v5 bridge (074)'));
      -- Q-3: the desk re-records in v5 every unlinked load that was already moving - a vehicle on it, or a status past
      -- Pending (a Friday export Delivered at Veroia with no truck on the record); a Cancelled load has nothing to re-record
      if nl.status is distinct from 'Cancelled'
         and (nl.truck_id is not null or nl.partner_id is not null or nl.status is distinct from 'Pending') then
        -- "I VS %s perase sto neo board; to palio ethniko fortio eiche ochima (%s): anathese tin xana"
        perform plan_h_notice('natl', 'legacy_nl_replaced',
          'zpcgVlMgJXMgz4DOrc+BzrHPg861IM+Dz4TOvyDOvc6tzr8gYm9hcmTCtyDPhM6/IM+AzrHOu865z4wgzrXOuM69zrnOus+MIM+Gzr/Pgc+Ezq/OvyDOtc6vz4fOtSDPjM+HzrfOvM6xICglcyk6IM6xzr3OrM64zrXPg86tIM+EzrfOvSDOvs6xzr3OrA==',
          array[v_ref, coalesce('truck ' || nl.truck_id, 'partner ' || nl.partner_id, 'status ' || coalesce(nl.status, '-'))],
          p_order, null, null, v_actor, v_role);
      end if;
    end loop;
  end if;
end
$f$;

  -- ===== PART 3: THE TWO BRIDGE TRIGGERS =====
  -- AFTER ... FOR EACH ROW, immediate: the bridge is re-cut before 071's deferred plan_chk_bridge_stop reads it at
  -- COMMIT. Both do nothing while plan_config is empty (they exist for the rollback and the tests before day L).
  CREATE FUNCTION public.plan_bridge_on_order() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$
begin
  if plan_cutover_day() is null then return null; end if;
  -- the common case first: an order that is not a VS and never was bridged is not the bridge's
  if new.veroia_switch is not true and (tg_op = 'INSERT' or old.veroia_switch is not true)
     and not exists (select 1 from shipments s where s.order_id = new.id and s.deleted_at is null) then
    return null;
  end if;
  if tg_op = 'UPDATE' and old.cross_dock_date is distinct from new.cross_dock_date
     and current_setting('plan.writer', true) is distinct from 'natl' then
    perform plan_h_bridge_unplan(new.id, null, 'trigger:plan_bridge_sync', 'trigger:plan_bridge_sync', 'system');
  end if;
  perform plan_bridge_sync(new.id, 'trigger:plan_bridge_sync');
  return null;
end
$f$;
  CREATE FUNCTION public.plan_bridge_on_stop() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$
declare v_sh bigint; v_o orders%rowtype;
begin
  if plan_cutover_day() is null then return null; end if;
  if new.order_id is null and (tg_op = 'INSERT' or old.order_id is null) then return null; end if;
  -- the common case first, as plan_bridge_on_order: a stop of an order that is not a VS and has no bridge, written
  -- without via_hub, is not the bridge's (a non-VS stop WITH via_hub is set back by the sync, B-99's rule)
  if (tg_op = 'INSERT' or old.order_id is not distinct from new.order_id) and not new.via_hub
     and not exists (select 1 from orders o where o.id = new.order_id and o.veroia_switch)
     and not exists (select 1 from shipments s where s.order_id = new.order_id and s.deleted_at is null) then
    return null;
  end if;
  if tg_op = 'UPDATE' then
    select id into v_sh from shipments where order_stop_id = new.id and deleted_at is null;
    if v_sh is not null and new.order_id is not distinct from old.order_id and new.deleted_at is null then
      if old.location_id is distinct from new.location_id and current_setting('plan.writer', true) is distinct from 'natl' then
        perform plan_h_bridge_place(new.id, old.location_id, new.location_id, 'trigger:plan_bridge_sync', 'system');
      end if;
      if old.pallets is distinct from new.pallets then
        perform plan_h_bridge_recut(v_sh, 'trigger:plan_bridge_sync', 'trigger:plan_bridge_sync', 'system');
      end if;
      select * into v_o from orders where id = new.order_id;
      if old.datetime is distinct from new.datetime and current_setting('plan.writer', true) is distinct from 'natl'
         and plan_h_vs_nat_side(v_o.direction, new.stop_type) then
        perform plan_h_bridge_unplan(new.order_id, new.id, 'trigger:plan_bridge_sync', 'trigger:plan_bridge_sync', 'system');
      end if;
    end if;
    if old.order_id is not null and old.order_id is distinct from new.order_id then
      perform plan_bridge_sync(old.order_id, 'trigger:plan_bridge_sync');
    end if;
  end if;
  if new.order_id is not null then perform plan_bridge_sync(new.order_id, 'trigger:plan_bridge_sync'); end if;
  return null;
end
$f$;
  CREATE TRIGGER plan_bridge_on_order AFTER INSERT OR UPDATE OF veroia_switch, cross_dock_date, deleted_at, status, direction
    ON public.orders FOR EACH ROW EXECUTE FUNCTION public.plan_bridge_on_order();
  CREATE TRIGGER plan_bridge_on_stop AFTER INSERT OR UPDATE OF location_id, pallets, deleted_at, stop_type, datetime, order_id
    ON public.order_stops FOR EACH ROW EXECUTE FUNCTION public.plan_bridge_on_stop();

  -- ===== PART 4: THE FREEZE, 028 AND 030 =====
  -- spec 2.2 / 3: from day L the old model takes no new row, from any path (the browser of yesterday in a service
  -- worker cache, the facade, SQL): the rule sits in the base (principle 4). UPDATE and soft delete of history are
  -- NOT cut here - the Worker cuts them by role (E16, Q-10). relay_* and nat_loading are not the old model.
  CREATE FUNCTION public.plan_legacy_frozen() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$
begin
  if plan_cutover_day() is not null then
    raise exception 'plan rule broken: legacy_frozen:% (the old national model is history from day %)', tg_table_name, plan_cutover_day()
      using errcode = '23514', hint = 'plan:legacy_frozen';
  end if;
  return new;
end
$f$;
  CREATE TRIGGER plan_legacy_frozen BEFORE INSERT ON public.national_loads FOR EACH ROW EXECUTE FUNCTION public.plan_legacy_frozen();
  CREATE TRIGGER plan_legacy_frozen BEFORE INSERT ON public.groupage_lines FOR EACH ROW EXECUTE FUNCTION public.plan_legacy_frozen();
  CREATE TRIGGER plan_legacy_frozen BEFORE INSERT ON public.consolidated_loads FOR EACH ROW EXECUTE FUNCTION public.plan_legacy_frozen();
  CREATE TRIGGER plan_legacy_frozen BEFORE INSERT ON public.local_moves FOR EACH ROW
    WHEN (new.move_kind = 'local') EXECUTE FUNCTION public.plan_legacy_frozen();
  -- 028 / 030 stop moving the old national loads once day L is in plan_config: the LIVE text + one line each,
  -- reversible byte for byte (the rollback replaces back and proves the md5 of PART 0). 069 stays: it moves the
  -- international's Cross-dock stop and the ramp, which v5 reads.
  FOR v_g IN SELECT * FROM (VALUES
      ('public.order_dates_follow()', a_028, b_028, 'a55eb83e75fc4e442ea026f4a6c858e5'),
      ('public.national_load_follow_order()', a_030, b_030, 'e6e1982837e46390b7a4dac514616ffb')) g(sig, a, b, m) LOOP
    SELECT prosrc INTO v_src FROM pg_proc WHERE oid = to_regprocedure(v_g.sig);
    IF (length(v_src) - length(replace(v_src, v_g.a, ''))) <> length(v_g.a) THEN
      RAISE EXCEPTION '074: the patch target is not in % exactly once - stop', v_g.sig;
    END IF;
    v_new := replace(v_src, v_g.a, v_g.b);
    IF replace(v_new, v_g.b, v_g.a) <> v_src OR md5(v_new) <> v_g.m THEN
      RAISE EXCEPTION '074: the generated text of % is not the one measured (md5 %) - stop', v_g.sig, md5(v_new);
    END IF;
    EXECUTE format('CREATE OR REPLACE FUNCTION %s() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS %L',
      split_part(v_g.sig, '(', 1), v_new);
  END LOOP;

  -- ===== PART 5: RIGHTS (born closed, principle 5) =====
  -- Only triggers call these (a trigger function needs no EXECUTE at fire time); the auditor's grants on
  -- plan_h_vs_in_v5 / plan_h_bridge_wanted come with 074b, where the checks that read them are seeded.
  FOR v_g IN SELECT * FROM unnest(ARRAY[
      'public.plan_h_vs_nat_side(text,text)', 'public.plan_h_vs_in_v5(bigint)', 'public.plan_h_bridge_wanted(bigint)',
      'public.plan_h_bridge_executed(bigint)', 'public.plan_h_vs_repoint(bigint,text,bigint,bigint,text,text,text)',
      'public.plan_h_bridge_drop(bigint[],text,text,text)', 'public.plan_h_bridge_retire(bigint,text,text,text)',
      'public.plan_h_bridge_unplan(bigint,bigint,text,text,text)', 'public.plan_h_bridge_recut(bigint,text,text,text)',
      'public.plan_h_bridge_place(bigint,bigint,bigint,text,text)', 'public.plan_bridge_sync(bigint,text)',
      'public.plan_bridge_on_order()', 'public.plan_bridge_on_stop()', 'public.plan_legacy_frozen()']) g(sig) LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated, service_role', v_g.sig);
  END LOOP;

  -- ===== PART 6: DAY L, THEN THE BACKFILL =====
  INSERT INTO public.plan_config (id, cutover_day, opened_at, opened_by) VALUES (1, c_cutover_day, now(), '074');
  FOR x IN SELECT id FROM public.orders WHERE veroia_switch AND deleted_at IS NULL ORDER BY id LOOP
    PERFORM public.plan_bridge_sync(x.id, '074 backfill');
    IF EXISTS (SELECT 1 FROM public.shipments WHERE order_id = x.id AND deleted_at IS NULL) THEN v_vs := v_vs + 1; END IF;
  END LOOP;

  -- ===== PART 7: THE TEST ROWS OF THE OLD MODEL (spec 2.2 step 1) =====
  IF (SELECT coalesce(array_agg(id ORDER BY id), '{}') FROM public.national_orders WHERE deleted_at IS NULL) <> c_tests_no
     OR (SELECT coalesce(array_agg(id ORDER BY id), '{}') FROM public.national_loads
          WHERE deleted_at IS NULL AND source_type IN ('National', 'Groupage')) <> c_tests_nl
     OR (SELECT coalesce(array_agg(id ORDER BY id), '{}') FROM public.consolidated_loads WHERE deleted_at IS NULL) <> c_tests_cl
     OR (SELECT coalesce(array_agg(id ORDER BY id), '{}') FROM public.groupage_lines WHERE deleted_at IS NULL) <> c_tests_gl THEN
    RAISE EXCEPTION '074: the live national orders / National-Groupage NL / CL / GL are not exactly the test rows measured 28/10 - stop, re-measure';
  END IF;
  FOR x IN SELECT 'national_orders' AS t, id, NULL::jsonb AS b FROM public.national_orders WHERE id = ANY (c_tests_no)
           UNION ALL SELECT 'national_loads', id, NULL FROM public.national_loads WHERE id = ANY (c_tests_nl)
           UNION ALL SELECT 'consolidated_loads', id, NULL FROM public.consolidated_loads WHERE id = ANY (c_tests_cl)
           UNION ALL SELECT 'groupage_lines', id, jsonb_build_object('status', status, 'cons_load_id', cons_load_id)
             FROM public.groupage_lines WHERE id = ANY (c_tests_gl) ORDER BY 1, 2 LOOP
    IF x.t = 'groupage_lines' THEN
      -- GROUPAGE LINES are never deleted (CLAUDE.md): released, as delete_order_cascade does
      UPDATE public.groupage_lines SET status = 'Unassigned', cons_load_id = NULL WHERE id = x.id;
      INSERT INTO public.plan_cutover_log (kind, table_name, row_id, reason, before_data) VALUES ('gl_unassigned', x.t, x.id, '074 tests', x.b);
    ELSE
      EXECUTE format('UPDATE public.%I SET deleted_at = now() WHERE id = $1 AND deleted_at IS NULL', x.t) USING x.id;
      INSERT INTO public.plan_cutover_log (kind, table_name, row_id, reason) VALUES ('test_cleanup', x.t, x.id, '074 tests');
    END IF;
    INSERT INTO public.audit_log (actor, role, action, table_name, record_id, before_data, after_data, created_at)
    VALUES ('074', 'system', CASE WHEN x.t = 'groupage_lines' THEN 'update' ELSE 'delete' END, x.t, x.id::text, x.b,
            jsonb_build_object('reason', 'test row of the old model (074, spec 2.2)'), now());
  END LOOP;

  -- ===== PART 8: PROOFS =====
  SELECT count(*) INTO v_sh FROM public.shipments WHERE deleted_at IS NULL;
  SELECT count(*) INTO v_nl FROM public.plan_cutover_log WHERE kind = 'nl_unlinked';
  SELECT coalesce(string_agg(l.row_id::text, ',' ORDER BY l.row_id), '-') INTO v_nlveh FROM public.plan_cutover_log l
   WHERE l.kind = 'nl_unlinked' AND l.before_data->>'status' IS DISTINCT FROM 'Cancelled'
     AND (l.before_data->>'truck_id' IS NOT NULL OR l.before_data->>'partner_id' IS NOT NULL
          OR l.before_data->>'status' IS DISTINCT FROM 'Pending');
  SELECT count(*) INTO v_via FROM public.order_stops WHERE via_hub;
  -- the bridge = the wanted stops, exactly (B-95's equality, spec 8)
  IF EXISTS (SELECT 1 FROM public.order_stops s WHERE s.order_id IS NOT NULL
              AND (plan_h_bridge_wanted(s.id) <> EXISTS (SELECT 1 FROM public.shipments b WHERE b.order_stop_id = s.id AND b.deleted_at IS NULL)
                   OR s.via_hub <> plan_h_bridge_wanted(s.id))) THEN
    RAISE EXCEPTION '074 proof: the bridges (or via_hub) are not exactly the national-side stops of the VS in v5';
  END IF;
  IF v_via <> v_sh OR (SELECT count(*) FROM public.shipment_pieces WHERE deleted_at IS NULL) <> v_sh THEN
    RAISE EXCEPTION '074 proof: bridges %, pieces %, via_hub % - expected equal', v_sh,
      (SELECT count(*) FROM public.shipment_pieces WHERE deleted_at IS NULL), v_via;
  END IF;
  IF v_nl <> v_vs THEN RAISE EXCEPTION '074 proof: % NL unlinked for % VS in v5', v_nl, v_vs; END IF;
  -- B-78's rule: no order lives in both models
  IF EXISTS (SELECT 1 FROM public.orders o WHERE o.deleted_at IS NULL
              AND EXISTS (SELECT 1 FROM public.shipments s WHERE s.order_id = o.id AND s.deleted_at IS NULL)
              AND EXISTS (SELECT 1 FROM public.national_loads nl WHERE nl.source_order_id = o.id AND nl.source_type = 'Direct' AND nl.deleted_at IS NULL)) THEN
    RAISE EXCEPTION '074 proof: an order has a bridge AND a live Direct national load';
  END IF;
  -- notices: only this transaction's (created_at = now()); an earlier 074 that was rolled back may have left its own
  IF (SELECT count(*) FROM public.piece_legs) + (SELECT count(*) FROM public.rt_stops) + (SELECT count(*) FROM public.plan_notices
        WHERE created_at = now() AND kind <> 'legacy_nl_replaced') <> 0 THEN
    RAISE EXCEPTION '074 proof: legs, stops or notices other than legacy_nl_replaced were written';
  END IF;
  IF (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.oid = ANY (ARRAY[
        'public.plan_bridge_sync(bigint,text)'::regprocedure, 'public.plan_h_vs_in_v5(bigint)'::regprocedure,
        'public.plan_h_bridge_wanted(bigint)'::regprocedure, 'public.plan_legacy_frozen()'::regprocedure])
        AND (has_function_privilege('anon', p.oid, 'EXECUTE') OR has_function_privilege('authenticated', p.oid, 'EXECUTE')
             OR has_function_privilege('service_role', p.oid, 'EXECUTE'))) <> 0
     OR has_table_privilege('service_role', 'public.plan_cutover_log', 'SELECT')
     OR has_table_privilege('anon', 'public.plan_cutover_log', 'SELECT') THEN
    RAISE EXCEPTION '074 proof: a new function or plan_cutover_log is open to an API role';
  END IF;
  IF (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.plan_vs_set_place(jsonb,text,text)'::regprocedure) <> 'c8814ab08d0a86cfb77b79a89b9ba8a8'
     OR (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.order_dates_follow()'::regprocedure) <> 'a55eb83e75fc4e442ea026f4a6c858e5'
     OR (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.national_load_follow_order()'::regprocedure) <> 'e6e1982837e46390b7a4dac514616ffb' THEN
    RAISE EXCEPTION '074 proof: a patched function does not hold its generated text';
  END IF;
  -- B-54: exactly six triggers more (2 bridge + 4 freeze), in the same block
  SELECT count(*) INTO v_trg1 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid
    JOIN pg_namespace ns ON ns.oid = c.relnamespace WHERE NOT t.tgisinternal AND t.tgenabled <> 'D' AND ns.nspname = 'public';
  IF v_trg1 <> v_trg0 + 6 THEN RAISE EXCEPTION '074 proof: triggers % -> %, expected +6', v_trg0, v_trg1; END IF;
  UPDATE monitoring.checks SET red_value = v_trg1 WHERE id = 'B-54' AND red_value = v_trg0;
  GET DIAGNOSTICS v_k = ROW_COUNT;
  IF v_k <> 1 THEN RAISE EXCEPTION '074: B-54 not updated (% rows)', v_k; END IF;
  RAISE NOTICE '074 OK: cutover %, bridges % on % VS, NL unlinked %, NL to re-record % [%], tests cleaned %/%/%/%, via_hub %, triggers % -> %, B-54 %, legs 0',
    c_cutover_day, v_sh, v_vs, v_nl, CASE WHEN v_nlveh = '-' THEN 0 ELSE cardinality(string_to_array(v_nlveh, ',')) END, v_nlveh,
    cardinality(c_tests_no), cardinality(c_tests_nl), cardinality(c_tests_cl), cardinality(c_tests_gl), v_via, v_trg0, v_trg1, v_trg1;
END;
  -- ===== what it did =====
  res := format('074 ran: cutover %s, bridges %s on %s VS, NL unlinked %s, NL to re-record %s [%s], tests cleaned %s/%s/%s/%s, via_hub %s, legs %s, triggers %s',
    public.plan_cutover_day(), (SELECT count(*) FROM public.shipments WHERE deleted_at IS NULL),
    (SELECT count(DISTINCT order_id) FROM public.shipments WHERE deleted_at IS NULL),
    (SELECT count(*) FROM public.plan_cutover_log WHERE kind = 'nl_unlinked'),
    (SELECT count(*) FROM public.plan_cutover_log WHERE kind = 'nl_unlinked' AND before_data->>'status' IS DISTINCT FROM 'Cancelled'
       AND (before_data->>'truck_id' IS NOT NULL OR before_data->>'partner_id' IS NOT NULL
       OR before_data->>'status' IS DISTINCT FROM 'Pending')),
    (SELECT coalesce(string_agg(row_id::text, ',' ORDER BY row_id), '-') FROM public.plan_cutover_log WHERE kind = 'nl_unlinked' AND before_data->>'status' IS DISTINCT FROM 'Cancelled'
       AND (before_data->>'truck_id' IS NOT NULL OR before_data->>'partner_id' IS NOT NULL
       OR before_data->>'status' IS DISTINCT FROM 'Pending')),
    (SELECT count(*) FROM public.plan_cutover_log WHERE kind = 'test_cleanup' AND table_name = 'national_orders'),
    (SELECT count(*) FROM public.plan_cutover_log WHERE kind = 'test_cleanup' AND table_name = 'national_loads'),
    (SELECT count(*) FROM public.plan_cutover_log WHERE kind = 'test_cleanup' AND table_name = 'consolidated_loads'),
    (SELECT count(*) FROM public.plan_cutover_log WHERE kind = 'gl_unassigned'),
    (SELECT count(*) FROM public.order_stops WHERE via_hub), (SELECT count(*) FROM public.piece_legs),
    (SELECT count(*) FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace ns ON ns.oid = c.relnamespace
      WHERE NOT t.tgisinternal AND t.tgenabled <> 'D' AND ns.nspname = 'public'));
  RAISE EXCEPTION 'DRY RUN 074 finished - EVERYTHING UNDONE, nothing kept. The block ran to its end  ||  %', res;
END
$dry$;
